  "name": "int_cart_contents",
  "layer": "intermediate",
  "materialized": "ephemeral",
  "schema": "main_intermediate",
  "description": "",
  "raw_sql": "-- Rolls cart_items up to one row per cart, and picks the cart's dominant merchant (the one\n-- on its highest-value line). That choice is a modeling decision with a cost, documented in\n-- the marts schema.yml rather than left for someone to discover.\nwith items as (select * from {{ ref('stg_bazaar__cart_items') }}),\n     products as (select * from {{ ref('stg_bazaar__products') }}),\n\njoined as (\n    select\n        items.cart_id,\n        items.product_id,\n        items.quantity,\n        products.merchant_id,\n        products.list_price,\n        items.quantity * products.list_price as line_value\n    from items\n    join products on products.product_id = items.product_id\n),\n\nranked as (\n    select *,\n           row_number() over (partition by cart_id order by line_value desc, merchant_id) as value_rank\n    from joined\n)\n\nselect\n    cart_id,\n    count(*)                       as distinct_products,\n    sum(quantity)                  as units,\n    round(sum(line_value), 2)      as cart_value,\n    max(case when value_rank = 1 then merchant_id end) as dominant_merchant_id\nfrom ranked\ngroup by cart_id",
  "compiled_sql": "-- Rolls cart_items up to one row per cart, and picks the cart's dominant merchant (the one\n-- on its highest-value line). That choice is a modeling decision with a cost, documented in\n-- the marts schema.yml rather than left for someone to discover.\nwith items as (select * from \"main_staging\".\"stg_bazaar__cart_items\"),\n     products as (select * from \"main_staging\".\"stg_bazaar__products\"),\n\njoined as (\n    select\n        items.cart_id,\n        items.product_id,\n        items.quantity,\n        products.merchant_id,\n        products.list_price,\n        items.quantity * products.list_price as line_value\n    from items\n    join products on products.product_id = items.product_id\n),\n\nranked as (\n    select *,\n           row_number() over (partition by cart_id order by line_value desc, merchant_id) as value_rank\n    from joined\n)\n\nselect\n    cart_id,\n    count(*)                       as distinct_products,\n    sum(quantity)                  as units,\n    round(sum(line_value), 2)      as cart_value,\n    max(case when value_rank = 1 then merchant_id end) as dominant_merchant_id\nfrom ranked\ngroup by cart_id",
  "refs": [
   "stg_bazaar__cart_items",
   "stg_bazaar__products"
  ],
