window.AE_SETUPS = { built: `
-- The project, built in dbt's own dependency order. Every statement below is the

-- SQL dbt compiled - the ref() calls already resolved into real table names.

CREATE SCHEMA IF NOT EXISTS main_staging;

CREATE SCHEMA IF NOT EXISTS main_marts;

-- marts · table
CREATE OR REPLACE TABLE main_marts.dim_dates AS
-- The one dimension you never source: generated, wider than the data, and every calendar
-- attribute anyone will group by. DuckDB's generate_series does the walking.
with days as (
    select cast(range as date) as date_day
    from range(date '2026-03-01', date '2026-10-01', interval 1 day)
)

select
    
    md5(concat_ws('|',
        coalesce(cast(date_day as varchar), '_null_')
    ))
          as date_key,
    date_day,
    year(date_day)                             as year_number,
    quarter(date_day)                          as quarter_number,
    month(date_day)                            as month_number,
    monthname(date_day)                        as month_name,
    day(date_day)                              as day_of_month,
    dayofweek(date_day)                        as day_of_week,
    dayname(date_day)                          as day_name,
    week(date_day)                             as week_of_year,
    dayofweek(date_day) in (0, 6)              as is_weekend
from days;

-- marts · table
CREATE OR REPLACE TABLE main_marts.dim_time_of_day AS
-- Hour grain, kept out of dim_dates on purpose: putting hours in the date dimension would
-- multiply it by 24 for no benefit, and "what are our peak hours" needs to group across all
-- 90 days at once.
with hours as (select cast(range as integer) as hour_24 from range(0, 24))

select
    hour_24                                    as time_key,
    hour_24,
    lpad(cast(hour_24 as varchar), 2, '0') || ':00-' ||
      lpad(cast(hour_24 as varchar), 2, '0') || ':59' as hour_label,
    case
        when hour_24 < 6  then 'overnight'
        when hour_24 < 11 then 'morning'
        when hour_24 < 14 then 'lunch'
        when hour_24 < 18 then 'afternoon'
        when hour_24 < 23 then 'evening'
        else 'late'
    end                                        as daypart,
    hour_24 between 9 and 18                   as is_business_hour
from hours;

-- staging · view
CREATE OR REPLACE VIEW main_staging.stg_bazaar__cart_items AS
with source as (select * from "raw"."cart_items"),

renamed as (
    select
        cart_id,
        product_id,
        quantity,
        cast(added_ts as timestamp) as added_at
    from source
)

select * from renamed;

-- staging · view
CREATE OR REPLACE VIEW main_staging.stg_bazaar__carts AS
with source as (select * from "raw"."carts"),

renamed as (
    select
        cart_id,
        user_id,
        cast(created_ts as timestamp) as created_at,
        status                       as cart_status
    from source
)

select * from renamed;

-- staging · view
CREATE OR REPLACE VIEW main_staging.stg_bazaar__merchants AS
with source as (select * from "raw"."merchants"),

renamed as (
    select
        merchant_id,
        merchant_name,
        category        as merchant_category,
        country         as merchant_country,
        tier            as merchant_tier,
        commission_pct,
        cast(joined_date as date) as joined_on
    from source
)

select * from renamed;

-- staging · view
CREATE OR REPLACE VIEW main_staging.stg_bazaar__order_items AS
with source as (select * from "raw"."order_items"),

renamed as (
    select
        order_id,
        line_no,
        product_id,
        merchant_id,        -- captured at time of sale, not looked up: see the b3 note
        quantity,
        unit_price,
        discount_amt,
        round(quantity * unit_price, 2)                 as gross_amount,
        round(quantity * unit_price - discount_amt, 2)  as net_amount
    from source
)

select * from renamed;

-- staging · view
CREATE OR REPLACE VIEW main_staging.stg_bazaar__orders AS
with source as (select * from "raw"."orders"),

renamed as (
    select
        order_id,
        user_id,
        cart_id,
        cast(order_ts as timestamp) as ordered_at,
        status                      as order_status,
        ship_country,
        currency,

        -- One boolean, defined once, instead of every downstream query inventing its own
        -- idea of which statuses count as money. Session b4's favourite line.
        order_status in ('paid', 'refunded') as is_settled
    from source
)

select * from renamed;

-- staging · view
CREATE OR REPLACE VIEW main_staging.stg_bazaar__products AS
with source as (select * from "raw"."products"),

renamed as (
    select
        product_id,
        merchant_id,
        sku,
        product_name,
        category    as product_category,
        list_price,
        unit_cost,
        cast(launched_date as date) as launched_on,
        status      as product_status,

        -- price_tier is MODELED here, not sourced: the business thinks in bands and the
        -- source only has a number. Defining it once is what stops three dashboards
        -- disagreeing about what "premium" means.
        case
            when list_price < 25 then 'budget'
            when list_price < 80 then 'mid'
            else 'premium'
        end as price_tier
    from source
)

select * from renamed;

-- staging · view
CREATE OR REPLACE VIEW main_staging.stg_bazaar__transactions AS
with source as (select * from "raw"."transactions"),

renamed as (
    select
        txn_id,
        order_id,
        cast(txn_ts as timestamp) as attempted_at,
        amount,                            -- signed: negative for refunds
        currency,
        payment_method,
        status                    as txn_status,
        coalesce(decline_reason, 'none') as decline_reason,
        psp_ref,

        -- Pre-split measures so every rate downstream has an additive numerator and an
        -- additive denominator, and nobody has to store a ratio.
        case when status = 'approved' then 1 else 0 end as is_approved,
        case when status = 'declined' then 1 else 0 end as is_declined,
        case when status = 'refunded' then 1 else 0 end as is_refund,
        case when status = 'approved' then amount else 0 end as approved_amount,
        case when status = 'declined' then amount else 0 end as declined_amount
    from source
)

select * from renamed;

-- staging · view
CREATE OR REPLACE VIEW main_staging.stg_bazaar__users AS
-- One model per source table. Staging does four things and nothing else:
-- rename, recast, light cleaning, and no joins. That discipline is why staging
-- models are cheap to read and safe to change.
with source as (select * from "raw"."users"),

renamed as (
    select
        user_id,
        email,
        cast(signup_ts as timestamp)            as signed_up_at,
        country                                 as user_country,
        coalesce(city, 'unknown')               as user_city,
        coalesce(acquisition_channel, 'unknown') as acquisition_channel,
        cast(is_guest as boolean)               as is_guest
    from source
)

select * from renamed;

-- marts · table
CREATE OR REPLACE TABLE main_marts.dim_merchants AS
-- Type 2 structure. dbt has a first-class answer for this - snapshots - and session b6
-- builds one. This model is the current-version view of it, so the mart layer stays
-- readable while the snapshot keeps the history.
with merchants as (select * from "main_staging"."stg_bazaar__merchants")

select
    
    md5(concat_ws('|',
        coalesce(cast(merchant_id as varchar), '_null_')
    ))
  as merchant_sk,
    merchant_id,
    merchant_name,
    merchant_category,
    merchant_country,
    merchant_tier,
    commission_pct,
    joined_on,
    joined_on                             as valid_from,
    cast('9999-12-31' as date)            as valid_to,
    true                                  as is_current
from merchants;

-- marts · table
CREATE OR REPLACE TABLE main_marts.dim_payment_methods AS
-- A small dimension that exists because grouping by a raw source string ('card_visa') is
-- not the grouping anyone wants. Built from the distinct values with the business grouping
-- attached, so a new method in the source shows up as 'unknown' rather than vanishing.
with methods as (
    select distinct payment_method from "main_staging"."stg_bazaar__transactions"
)

select
    
    md5(concat_ws('|',
        coalesce(cast(payment_method as varchar), '_null_')
    ))
 as payment_method_sk,
    payment_method,
    case payment_method
        when 'card_visa'       then 'Visa'
        when 'card_mastercard' then 'Mastercard'
        when 'card_amex'       then 'Amex'
        when 'paynow'          then 'PayNow'
        when 'grabpay'         then 'GrabPay'
        when 'bank_transfer'   then 'Bank transfer'
        else 'unknown'
    end as method_label,
    case
        when payment_method like 'card_%' then 'card'
        when payment_method in ('paynow', 'bank_transfer') then 'bank'
        when payment_method = 'grabpay' then 'wallet'
        else 'unknown'
    end as method_family,
    payment_method like 'card_%' as is_card
from methods;

-- marts · table
CREATE OR REPLACE TABLE main_marts.dim_products AS
-- Flat and wide, not snowflaked: the merchant's name rides along even though dim_merchants
-- has it. One less join in every analyst query and every query an AI agent writes.
with products as (select * from "main_staging"."stg_bazaar__products"),
     merchants as (select * from "main_staging"."stg_bazaar__merchants")

select
    
    md5(concat_ws('|',
        coalesce(cast(products.product_id as varchar), '_null_')
    ))
 as product_sk,
    products.product_id,
    products.sku,
    products.product_name,
    products.product_category,
    products.merchant_id,
    merchants.merchant_name,
    products.list_price,
    products.unit_cost,
    products.price_tier,
    products.product_status,
    products.launched_on
from products
join merchants on merchants.merchant_id = products.merchant_id;

-- marts · table
CREATE OR REPLACE TABLE main_marts.dim_users AS
-- Type 1: attributes overwritten in place. Nobody has ever asked for the history of a
-- shopper's city. tenure_bucket is banded here so no dashboard writes its own CASE.
with users as (select * from "main_staging"."stg_bazaar__users")

select
    
    md5(concat_ws('|',
        coalesce(cast(user_id as varchar), '_null_')
    ))
   as user_sk,
    user_id,
    user_country,
    user_city,
    acquisition_channel,
    cast(signed_up_at as date)         as signed_up_on,
    case
        when date_diff('day', cast(signed_up_at as date), date '2026-06-29') < 90  then 'new'
        when date_diff('day', cast(signed_up_at as date), date '2026-06-29') < 365 then '3-12m'
        else '1y+'
    end                                as tenure_bucket,
    is_guest
from users;

-- marts · table
CREATE OR REPLACE TABLE main_marts.fct_carts AS
-- GRAIN: one row per cart. Demand that never became revenue - without this fact, "sales
-- fell" and "people stopped wanting to buy" look identical.
with  __dbt__cte__int_cart_contents as (
-- Rolls cart_items up to one row per cart, and picks the cart's dominant merchant (the one
-- on its highest-value line). That choice is a modeling decision with a cost, documented in
-- the marts schema.yml rather than left for someone to discover.
with items as (select * from "main_staging"."stg_bazaar__cart_items"),
     products as (select * from "main_staging"."stg_bazaar__products"),

joined as (
    select
        items.cart_id,
        items.product_id,
        items.quantity,
        products.merchant_id,
        products.list_price,
        items.quantity * products.list_price as line_value
    from items
    join products on products.product_id = items.product_id
),

ranked as (
    select *,
           row_number() over (partition by cart_id order by line_value desc, merchant_id) as value_rank
    from joined
)

select
    cart_id,
    count(*)                       as distinct_products,
    sum(quantity)                  as units,
    round(sum(line_value), 2)      as cart_value,
    max(case when value_rank = 1 then merchant_id end) as dominant_merchant_id
from ranked
group by cart_id
), carts as (select * from "main_staging"."stg_bazaar__carts"),
     contents as (select * from __dbt__cte__int_cart_contents),
     orders as (select * from "main_staging"."stg_bazaar__orders"),
     dim_users as (select * from "main_marts"."dim_users"),
     dim_merchants as (select * from "main_marts"."dim_merchants"),
     dim_dates as (select * from "main_marts"."dim_dates")

select
    
    md5(concat_ws('|',
        coalesce(cast(carts.cart_id as varchar), '_null_')
    ))
   as cart_sk,

    coalesce(dim_dates.date_key, '-1')       as date_key,
    hour(carts.created_at)                   as time_key,
    coalesce(dim_users.user_sk, '-1')        as user_sk,
    coalesce(dim_merchants.merchant_sk, '-1') as merchant_sk,

    carts.cart_id,                            -- degenerate
    orders.order_id,                          -- null when abandoned

    contents.distinct_products,
    contents.units,
    contents.cart_value,
    orders.order_id is not null              as is_converted,
    case when orders.order_id is null then contents.cart_value else 0 end as abandoned_value,
    case
        when orders.order_id is null then null
        else round(date_diff('second', carts.created_at, orders.ordered_at) / 60.0, 1)
    end                                      as minutes_to_order
from carts
join contents on contents.cart_id = carts.cart_id
left join orders        on orders.cart_id = carts.cart_id
left join dim_dates     on dim_dates.date_day = cast(carts.created_at as date)
left join dim_users     on dim_users.user_id = carts.user_id
left join dim_merchants on dim_merchants.merchant_id = contents.dominant_merchant_id and dim_merchants.is_current;

-- marts · table
CREATE OR REPLACE TABLE main_marts.fct_order_items AS
-- GRAIN: one row per product line on one order. The revenue fact.
-- Dimension keys resolved with LEFT JOIN and coalesced to the unknown member: an inner join
-- here would silently drop a fact row, and silently-missing revenue is the worst failure
-- mode in the whole project.
with  __dbt__cte__int_order_lines_enriched as (
-- Intermediate models are the joins staging is not allowed to do. They are ephemeral: dbt
-- inlines them into the models that ref() them, so nothing is materialized and nobody can
-- query a half-finished shape by accident.
with lines as (select * from "main_staging"."stg_bazaar__order_items"),
     orders as (select * from "main_staging"."stg_bazaar__orders"),
     products as (select * from "main_staging"."stg_bazaar__products"),
     merchants as (select * from "main_staging"."stg_bazaar__merchants")

select
    lines.order_id,
    lines.line_no,
    orders.user_id,
    lines.product_id,
    lines.merchant_id,
    orders.ordered_at,
    orders.is_settled,
    lines.quantity,
    lines.unit_price,
    lines.gross_amount,
    lines.discount_amt,
    lines.net_amount,
    round(lines.net_amount * merchants.commission_pct, 2)      as commission_amount,
    round(lines.quantity * products.unit_cost, 2)              as cost_amount,
    round(lines.net_amount - lines.quantity * products.unit_cost, 2) as margin_amount
from lines
join orders    on orders.order_id = lines.order_id
join products  on products.product_id = lines.product_id
join merchants on merchants.merchant_id = lines.merchant_id
), lines as (select * from __dbt__cte__int_order_lines_enriched),
     dim_users as (select * from "main_marts"."dim_users"),
     dim_merchants as (select * from "main_marts"."dim_merchants"),
     dim_products as (select * from "main_marts"."dim_products"),
     dim_dates as (select * from "main_marts"."dim_dates")

select
    
    md5(concat_ws('|',
        coalesce(cast(lines.order_id as varchar), '_null_'),
        coalesce(cast(lines.line_no as varchar), '_null_')
    ))
 as order_item_sk,

    coalesce(dim_dates.date_key, '-1')      as date_key,
    hour(lines.ordered_at)                  as time_key,
    coalesce(dim_users.user_sk, '-1')       as user_sk,
    coalesce(dim_merchants.merchant_sk, '-1') as merchant_sk,
    coalesce(dim_products.product_sk, '-1') as product_sk,

    lines.order_id,                          -- degenerate dimension
    lines.line_no,                           -- degenerate dimension

    lines.quantity                          as units,
    lines.unit_price,                        -- a rate, not additive: kept for reference
    lines.gross_amount,
    lines.discount_amt                      as discount_amount,
    lines.net_amount,
    lines.commission_amount,
    lines.cost_amount,
    lines.margin_amount,
    lines.is_settled
from lines
left join dim_dates     on dim_dates.date_day = cast(lines.ordered_at as date)
left join dim_users     on dim_users.user_id = lines.user_id
left join dim_merchants on dim_merchants.merchant_id = lines.merchant_id and dim_merchants.is_current
left join dim_products  on dim_products.product_id = lines.product_id;

-- marts · table
CREATE OR REPLACE TABLE main_marts.fct_transactions AS
-- GRAIN: one row per payment attempt. Approvals, declines and refunds all live here, and
-- amount is signed so SUM over approved plus refunded is net settled money.
with txns as (select * from "main_staging"."stg_bazaar__transactions"),
     orders as (select * from "main_staging"."stg_bazaar__orders"),
     dim_users as (select * from "main_marts"."dim_users"),
     dim_methods as (select * from "main_marts"."dim_payment_methods"),
     dim_dates as (select * from "main_marts"."dim_dates")

select
    
    md5(concat_ws('|',
        coalesce(cast(txns.txn_id as varchar), '_null_')
    ))
      as txn_sk,

    coalesce(dim_dates.date_key, '-1')        as date_key,
    hour(txns.attempted_at)                   as time_key,
    coalesce(dim_users.user_sk, '-1')         as user_sk,
    coalesce(dim_methods.payment_method_sk, '-1') as payment_method_sk,

    txns.txn_id,                               -- degenerate
    txns.order_id,                             -- degenerate, the drill-down path

    txns.amount                               as attempt_amount,
    txns.approved_amount,
    txns.declined_amount,
    txns.is_approved,
    txns.is_declined,
    txns.is_refund,
    txns.decline_reason
from txns
join orders on orders.order_id = txns.order_id
left join dim_dates   on dim_dates.date_day = cast(txns.attempted_at as date)
left join dim_users   on dim_users.user_id = orders.user_id
left join dim_methods on dim_methods.payment_method = txns.payment_method;

-- marts · table
CREATE OR REPLACE TABLE main_marts.mart_funnel_daily AS
-- GRAIN: one day. The decomposition mart: sales = carts x conversion x AOV, so a drop is
-- always one of those three moving and the arithmetic is checkable in one place.
-- Note it joins three PRE-AGGREGATED day-grain sets, never two facts directly.
with carts as (
    select dates.date_day as activity_date,
           count(*) as carts_created,
           sum(case when c.is_converted then 1 else 0 end) as carts_converted,
           round(sum(c.cart_value), 2) as cart_value,
           round(sum(c.abandoned_value), 2) as abandoned_value
    from "main_marts"."fct_carts" c
    join "main_marts"."dim_dates" dates on dates.date_key = c.date_key
    group by 1
),
sales as (
    select dates.date_day as activity_date,
           count(distinct f.order_id) as paid_orders,
           round(sum(f.net_amount), 2) as net_revenue,
           sum(f.units) as units
    from "main_marts"."fct_order_items" f
    join "main_marts"."dim_dates" dates on dates.date_key = f.date_key
    where f.is_settled
    group by 1
),
payments as (
    select dates.date_day as activity_date,
           count(*) as payment_attempts,
           sum(t.is_declined) as declines,
           round(sum(t.declined_amount), 2) as declined_amount
    from "main_marts"."fct_transactions" t
    join "main_marts"."dim_dates" dates on dates.date_key = t.date_key
    group by 1
)

select
    carts.activity_date,
    carts.carts_created,
    carts.carts_converted,
    carts.cart_value,
    carts.abandoned_value,
    coalesce(sales.paid_orders, 0)       as paid_orders,
    coalesce(sales.net_revenue, 0)       as net_revenue,
    coalesce(sales.units, 0)             as units,
    coalesce(payments.payment_attempts, 0) as payment_attempts,
    coalesce(payments.declines, 0)       as declines,
    coalesce(payments.declined_amount, 0) as declined_amount
from carts
left join sales    on sales.activity_date = carts.activity_date
left join payments on payments.activity_date = carts.activity_date;

-- marts · table
CREATE OR REPLACE TABLE main_marts.mart_hourly_transactions AS
-- GRAIN: one date-hour. Serves peak-hour, staffing and deploy-window questions. Built from
-- the payments fact because the question is about when money MOVES.
with facts as (select * from "main_marts"."fct_transactions"),
     dates as (select * from "main_marts"."dim_dates"),
     hours as (select * from "main_marts"."dim_time_of_day")

select
    dates.date_day        as activity_date,
    dates.day_name,
    dates.is_weekend,
    hours.hour_24,
    hours.hour_label,
    hours.daypart,
    count(*)              as attempts,
    sum(facts.is_approved) as approvals,
    sum(facts.is_declined) as declines,
    round(sum(facts.approved_amount), 2) as approved_amount,
    round(sum(facts.declined_amount), 2) as declined_amount,
    count(distinct facts.order_id) as orders_touched
from facts
join dates on dates.date_key = facts.date_key
join hours on hours.time_key = facts.time_key
group by 1, 2, 3, 4, 5, 6;

-- marts · table
CREATE OR REPLACE TABLE main_marts.mart_merchant_daily AS
-- GRAIN: one merchant per day. Serves "which merchant dropped", revenue by tier, and the
-- merchant scorecard. Ratios ship as numerator and denominator, never as the ratio.
with facts as (select * from "main_marts"."fct_order_items"),
     dims as (select * from "main_marts"."dim_merchants"),
     dates as (select * from "main_marts"."dim_dates")

select
    dates.date_day                    as activity_date,
    dims.merchant_id,
    dims.merchant_name,
    dims.merchant_category,
    dims.merchant_tier,
    count(distinct facts.order_id)    as orders,
    sum(facts.units)                  as units,
    round(sum(facts.gross_amount), 2) as gross_revenue,
    round(sum(facts.discount_amount), 2) as discounts,
    round(sum(facts.net_amount), 2)   as net_revenue,
    round(sum(facts.commission_amount), 2) as commission,
    round(sum(facts.margin_amount), 2) as margin,
    round(sum(facts.net_amount), 2)   as aov_numerator,
    count(distinct facts.order_id)    as aov_denominator
from facts
join dates on dates.date_key = facts.date_key
join dims  on dims.merchant_sk = facts.merchant_sk
where facts.is_settled
group by 1, 2, 3, 4, 5;` };
